import{_ as t,o as a,c as r,a5 as d}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"通知と疎結合 — Observer・Event・Mediator","description":"","frontmatter":{"title":"通知と疎結合 — Observer・Event・Mediator","study":{"source":"設計の手帖","kind":"本文","status":"既存原稿","summary":"通知は直接の結び付きを減らします。その代わり、呼び出しの流れと寿命を見えるようにする必要があります。"}},"headers":[],"relativePath":"design/notebook/events.md","filePath":"design/notebook/events.md"}'),o={name:"design/notebook/events.md"};function i(n,e,l,s,h,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="通知と疎結合-—-observer・event・mediator" tabindex="-1">通知と疎結合 — Observer・Event・Mediator <a class="header-anchor" href="#通知と疎結合-—-observer・event・mediator" aria-label="Permalink to &quot;通知と疎結合 — Observer・Event・Mediator&quot;">​</a></h1><p>通知は直接の結び付きを減らします。その代わり、呼び出しの流れと寿命を見えるようにする必要があります。</p><p>02 · パターンを道具にする / Observer とイベント設計 / Publish facts, manage lifetimes / 応用 / 9分</p><p>タグ: Observer / Event / Mediator / 購読 / イベント駆動</p><h2 id="observer-変化を購読者へ知らせる" tabindex="-1">Observer：変化を購読者へ知らせる <a class="header-anchor" href="#observer-変化を購読者へ知らせる" aria-label="Permalink to &quot;Observer：変化を購読者へ知らせる&quot;">​</a></h2><div><p>在庫が変わるたびに一覧・通知・監査へ知らせたいとき、発行側は購読者の詳細を知らずに通知できます。<code>InventoryChanged</code>、<code>InventoryObserver</code>、<code>OnInventoryChanged</code> といった名前が手がかりです。</p><p>C# では event とデリゲートで表せます。C++ ではコールバックや接続オブジェクトで表すことがあります。解除忘れがあると、C++ では破棄後の対象を参照し、C# では長寿命の発行側が購読者を保持し続けることがあります。</p></div><h2 id="イベントは「起きた事実」、コマンドは「実行してほしい要求」" tabindex="-1">イベントは「起きた事実」、コマンドは「実行してほしい要求」 <a class="header-anchor" href="#イベントは「起きた事実」、コマンドは「実行してほしい要求」" aria-label="Permalink to &quot;イベントは「起きた事実」、コマンドは「実行してほしい要求」&quot;">​</a></h2><div><div class="table-scroll"><table><thead><tr><th>種類</th><th>名前の例</th><th>考えること</th></tr></thead><tbody><tr><td>コマンド</td><td>PlaceOrder / CancelOrderCommand</td><td>誰が受け付け、成功・失敗を誰へ返すか</td></tr><tr><td>イベント</td><td>OrderPlaced / PaymentFailed</td><td>いつ確定した事実か、誰へ何回届くか</td></tr></tbody></table></div><p>同じプロセス内で即時に通知する仕組みと、メッセージブローカー経由の非同期配信は、失敗の扱いが異なります。「イベントだから非同期」「必ず一回届く」とは限りません。外部配信では重複、順序、再試行、トランザクションとの境界を設計します。</p></div><h2 id="mediator-調整の窓口を作る" tabindex="-1">Mediator：調整の窓口を作る <a class="header-anchor" href="#mediator-調整の窓口を作る" aria-label="Permalink to &quot;Mediator：調整の窓口を作る&quot;">​</a></h2><div><p>画面部品同士が多数の相手を知る代わりに、<code>DialogMediator</code> が調整します。要求を Handler へ振り分けるメディエーターライブラリもあります。ただし、窓口が何でも知る巨大な司令塔になれば別の問題を作ります。Handler を増やす前に、普通のメソッド呼び出しで十分か検討します。</p></div><h2 id="導入前に決めておく四つのこと" tabindex="-1">導入前に決めておく四つのこと <a class="header-anchor" href="#導入前に決めておく四つのこと" aria-label="Permalink to &quot;導入前に決めておく四つのこと&quot;">​</a></h2><div><ul><li>発行元と購読者の寿命。誰がいつ購読を解除するか。</li><li>購読者の例外を、発行元へ返すか、記録して継続するか。</li><li>同期か非同期か。順序やスレッドの前提はあるか。</li><li>外部配信なら、同じ通知を二回処理しても壊れないか。</li></ul><aside class="article-note"><strong>小さく始める</strong><p>一対一の処理なら、直接呼び出す方が追いやすい場合があります。イベントは依存を消すのではなく、通知の契約へ移す方法です。</p></aside></div><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><p>画面を閉じたあとも、長寿命サービスの event に登録した画面が残りませんか？</p><h2 id="この章の参考資料" tabindex="-1">この章の参考資料 <a class="header-anchor" href="#この章の参考資料" aria-label="Permalink to &quot;この章の参考資料&quot;">​</a></h2><ul><li><a href="https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines" target="_blank" rel="noreferrer">C++ Core Guidelines</a> — Bjarne Stroustrup / Herb Sutter ほか。インターフェース、所有権、クラス設計の指針。規格書そのものではありません。</li><li><a href="https://martinfowler.com/bliki/CQRS.html" target="_blank" rel="noreferrer">CQRS</a> — Martin Fowler。更新用と参照用のモデルを分ける考え方と、複雑性の注意点。</li></ul><p><a href="/study/design/naming.html">クラス名辞典</a> / <a href="/study/design/pattern-index.html">パターン一覧</a> / <a href="/study/design/notebook-references.html">手帖の参考資料</a></p>',17)])])}const v=t(o,[["render",i]]);export{p as __pageData,v as default};
